files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #f5f5f5;
}

/* === Текст над изображением === */
.content {
  text-align: center;
  margin-bottom: 30px;
}

.title {
  margin: 0 0 10px;
  font-size: 32px;
  color: #2c3e50;
}

.description {
  margin: 0;
  font-size: 18px;
  color: #666;
}

/* === Контейнер изображения === */
.image-container {
  position: relative;
  width: 774px;
  height: 1161px;
  border: 2px solid #2c3e50;
  border-radius: 8px;
  overflow: hidden;
}

/* === Фоновое изображение === */
.background-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('../images/photo-1620694563886-c3a80ec55f41.avif');
  background-size: cover;
  background-position: center;
}

/* === Прямоугольник для размытия === */
.blur-box {
  position: absolute;
  top: 60px;
  left: 60px;
  right: 60px;
  bottom: 200px;
  background-color: rgba(255, 255, 255, 0.4);
  border: 2px solid #000;
  border-radius: 8px;
}

/* === Задание: добавить @supports с backdrop-filter === */
/* Здесь ваш код: */
@supports (backdrop-filter: blur(5px)) {
  .blur-box {
    background-color: transparent;
    backdrop-filter: blur(5px);
  }
}
